'use server'

import { updateTag } from 'next/cache'

export interface Post {
  id: string
  title: string
  content: string
}

const posts: Post[] = [
  { id: '1', title: 'First Post', content: 'Hello world!' },
]

export async function getPosts(): Promise<Post[]> {
  return posts
}

export async function createPost(formData: FormData) {
  const title = (formData?.get?.('title') as string) || 'Untitled'
  const content = (formData?.get?.('content') as string) || ''

  const newPost: Post = {
    id: String(Date.now()),
    title,
    content,
  }

  posts.push(newPost)

  // Immediately expire the "posts" cache tag so the next page load waits for fresh data
  // rather than serving stale cached content (read-your-own-writes)
  updateTag('posts')

  return newPost
}

